param([Parameter(Mandatory)][ValidateSet('BASELINE','REMEDIATION')][string]$Condition)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$result=Join-Path $root 'backend\experiments\results\experiment-1-23\probe';$dir=Join-Path $result $Condition;$staging=Join-Path $root "backend\experiments\results\experiment-1-23\collector-staging\PROBE-$Condition";New-Item -ItemType Directory -Force -Path $dir,$staging|Out-Null;$signal=Join-Path $staging 'STOP-COLLECTOR';$out=Join-Path $staging 'pool-metrics.jsonl';$summary=Join-Path $staging 'pool-metrics.jsonl.summary.json';$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-diagnostic-pool-until-stop.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',$out,'-SummaryPath',$summary,'-StopSignalPath',$signal,'-IntervalMilliseconds','1000','-MaxDurationSeconds','300') -WindowStyle Hidden -PassThru;Start-Sleep -Seconds 2;New-Item -ItemType File -Path (Join-Path $staging 'STOP-COLLECTOR.tmp')|Out-Null;Move-Item -Force (Join-Path $staging 'STOP-COLLECTOR.tmp') $signal;$p.WaitForExit(10000)|Out-Null;if(-not$p.HasExited){$p.Kill();throw 'COLLECTOR_STOP_TIMEOUT'};$summaryObj=Get-Content $summary -Raw|ConvertFrom-Json;if($summaryObj.collectorStatus-ne'COLLECTOR_STOPPED_BY_SIGNAL'-or-not$summaryObj.stopSignalObserved){throw 'Collector probe failed'};[ordered]@{condition=$Condition;status='CORE_BOUND_COLLECTOR_PROBE_READY';collector=$summaryObj;warmup=0;k6=0;core=0}|ConvertTo-Json -Depth 10|Set-Content (Join-Path $dir 'probe-summary.json') -Encoding UTF8;Write-Output 'CORE_BOUND_COLLECTOR_PROBE_READY'
